<?php require_once '../config/auth.php'; require_role('admin'); $pdo=db(); $counts=[]; foreach(['siswa','guru','kelas','jurusan'] as $t){$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();} $jurusan=$pdo->query('SELECT j.nama_jurusan,COUNT(s.nis) total FROM jurusan j LEFT JOIN kelas k ON k.id_jurusan=j.id_jurusan LEFT JOIN siswa s ON s.id_kelas=k.id_kelas GROUP BY j.id_jurusan ORDER BY j.nama_jurusan')->fetchAll(); $avg=$pdo->query('SELECT mp.nama_mapel,ROUND(AVG(n.nilai_akhir),2) rata FROM mata_pelajaran mp LEFT JOIN nilai n ON n.id_mapel=mp.id_mapel GROUP BY mp.id_mapel ORDER BY mp.nama_mapel')->fetchAll(); $page_title='Dashboard Admin'; require '../includes/header.php'; require '../includes/sidebar.php'; require '../includes/flash.php'; ?><h2>Dashboard Admin</h2><div class="row g-3 mb-4"><?php foreach(['siswa'=>'Siswa','guru'=>'Guru','kelas'=>'Kelas','jurusan'=>'Jurusan'] as $k=>$v): ?><div class="col-6 col-xl-3"><div class="card stat p-3"><small><?= $v ?></small><h2><?= $counts[$k] ?></h2></div></div><?php endforeach; ?></div><div class="row g-4"><div class="col-lg-6"><div class="card p-3"><h5>Siswa per Jurusan</h5><?php foreach($jurusan as $r): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($r['nama_jurusan']) ?></span><strong><?= $r['total'] ?></strong></div><?php endforeach; ?></div></div><div class="col-lg-6"><div class="card p-3"><h5>Rata-rata Nilai per Mapel</h5><?php foreach($avg as $r): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($r['nama_mapel']) ?></span><strong><?= $r['rata'] ?? '-' ?></strong></div><?php endforeach; ?></div></div></div><?php require '../includes/footer.php';
